/*
 * Build envelope for listDueNextActions.
 * - organizationId, connectionId, serviceId are bound server-side; body is a claim.
 * - workflowId, workflowRevision, n8nExecutionId come from $workflow and $execution.
 * - idempotencyKey is the list-level window key; per-item keys are derived downstream.
 * - correlationId rides the whole flow (tracking only).
 * - triggerLabel: 'TICK_15M' | 'DAILY_DIGEST'.
 * - No Date.now() / Math.random(): window key is fixed-length UTC minute bucket;
 *   correlationId is sha-256 over stable fields.
 */
const slug = (s) => String(s || '').replace(/[^A-Za-z0-9._:-]/g, '').slice(0, 128);
function sha256Hex(s) {
  // crypto.subtle is unavailable in legacy n8n-nodes-base.function; we use a
  // deterministic 64-bit FNV-1a hash hex-encoded to 16 hex chars (sufficient
  // for correlation id stability; not a security primitive).
  let h = 0xcbf29ce484222325n;
  const prime = 0x100000001b3n;
  const bytes = String(s);
  for (let i = 0; i < bytes.length; i++) {
    h = (h ^ BigInt(bytes.charCodeAt(i))) & 0xffffffffffffffffn;
    h = (h * prime) & 0xffffffffffffffffn;
  }
  return h.toString(16).padStart(16, '0');
}
const minuteBucket = $now.toUTC().toISO().slice(0, 16).replace(/[-:T]/g, '');
const triggerLabel = ($env.N8N_TRIGGER_LABEL || 'TICK_15M');
const stableSeed = [
  slug($workflow.id),
  String($workflow.revision || 2),
  slug($execution.id),
  triggerLabel,
  minuteBucket
].join('|');
const correlationId = 'corr-' + sha256Hex(stableSeed);
const idemWindow = 'sla-' + triggerLabel.toLowerCase().replace(/[^a-z0-9_-]/g,'') + '-' + minuteBucket;
const envelope = {
  schemaVersion: '1',
  commandId: ('cmd-' + idemWindow).slice(0, 64),
  commandName: 'listDueNextActions',
  idempotencyKey: idemWindow,
  correlationId: correlationId,
  organizationId: $env.HRP_AUTOMATION_ORG_ID,
  source: { kind: 'HRP_UI', provider: 'HRP_UI', connectionId: null },
  actor: { kind: 'SERVICE', serviceId: $env.HRP_AUTOMATION_SERVICE_ID },
  occurredAt: $now.toUTC().toISO(),
  automationSource: {
    kind: 'N8N_AUTOMATION',
    workflowId: slug($workflow.id),
    workflowRevision: 2,
    n8nExecutionId: slug($execution.id),
    workflowLabel: 'sla-reminder-crm',
    sourceEventId: triggerLabel
  },
  operation: {
    op: 'listDueNextActions',
    payload: {
      schemaVersion: '1',
      statusFilter: 'OPEN_OR_DUE',
      pageSize: 200
    }
  }
};
const rawBody = JSON.stringify(envelope);
return [
  {
    json: {
      envelope: envelope,
      rawBody: rawBody,
      triggerLabel: triggerLabel,
      signerProfile: 'BLOCKED_BY_N8N_SIGNER_DECISION'
    }
  }
];

/*
 * Filter due-list response:
 *   - DROP status !== 'OPEN'
 *   - DROP snoozeMode === 'SNOOZED' (notification-only; does NOT mutate SLA / canonical state)
 *   - BUCKET each surviving item by time-to-dueAt:
 *       DUE_SOON : 0 < dt <= 60 min
 *       OVERDUE  : dt <= 0
 *   - Output ONE logical item per nextActionId (C-N11-02).
 *   - Sort by (dueAt, nextActionId) so the order is deterministic and reorder-safe.
 *   - organizationId is server-resolved (registry bound); workflow never treats body as authority.
 *   - Supervisor lookup uses $env.N8N_FIXTURE_SUPERVISOR_MAP (assignedToRedacted -> supervisorRedacted).
 *     Missing owner AND missing supervisor => routing = 'FALLBACK' (no misroute, AC #5).
 */
const __in = $input.first().json || {};
const items = (__in.items || (__in.data && __in.data.items)) || [];
const triggerLabel = ($node["Build envelope (listDueNextActions)"].json.triggerLabel || 'TICK_15M');
const orgId = ($node["Build envelope (listDueNextActions)"].json.envelope.organizationId) || 'unknown-org';
const correlationId = $node["Build envelope (listDueNextActions)"].json.envelope.correlationId;
let supervisorMap = {};
try { supervisorMap = JSON.parse($env.N8N_FIXTURE_SUPERVISOR_MAP || '{}'); } catch (_e) { supervisorMap = {}; }
const now = Date.parse($now.toUTC().toISO());
const filtered = [];
for (const it of items) {
  if (!it || !it.nextActionId) continue;
  if (it.status !== 'OPEN') continue;
  if (it.snoozeMode === 'SNOOZED') continue;
  const dt = Date.parse(it.dueAt) - now;
  let slaBucket;
  if (dt <= 0) slaBucket = 'OVERDUE';
  else if (dt <= 60 * 60 * 1000) slaBucket = 'DUE_SOON';
  else continue;
  filtered.push({
    nextActionId: it.nextActionId,
    organizationId: orgId,
    assignedToRedacted: it.assignedToRedacted || null,
    supervisorRedacted: (supervisorMap[it.assignedToRedacted] || it.supervisorRedacted || null),
    slaBucket: slaBucket,
    dueAt: it.dueAt
  });
}
filtered.sort((a, b) => {
  if (a.dueAt !== b.dueAt) return a.dueAt < b.dueAt ? -1 : 1;
  return a.nextActionId < b.nextActionId ? -1 : (a.nextActionId > b.nextActionId ? 1 : 0);
});
const routed = filtered.map((it) => {
  const escalate = it.slaBucket === 'OVERDUE' && it.supervisorRedacted && it.supervisorRedacted !== 'NONE';
  const audience = escalate ? 'SUPERVISOR' : 'OWNER';
  const recipient = escalate ? it.supervisorRedacted : it.assignedToRedacted;
  const routing = (!recipient || recipient === 'NONE') ? 'FALLBACK' : 'SEND';
  return {
    nextActionId: it.nextActionId,
    organizationId: it.organizationId,
    slaBucket: it.slaBucket,
    audience: audience,
    recipientRedacted: routing === 'FALLBACK' ? null : recipient,
    routing: routing,
    dueAt: it.dueAt
  };
});
return [
  {
    json: {
      triggerLabel: triggerLabel,
      correlationId: correlationId,
      organizationId: orgId,
      totalSeen: items.length,
      totalKept: routed.length,
      items: routed,
      noItems: items.length === 0
    }
  }
];

/*
 * Build ONE sendSyntheticReminder envelope per surviving nextActionId.
 * - Stable idempotencyKey = 'rem-' + dayKey + '-' + nextActionId + '-' + audience + '-' + workflowRevision.
 * - dayKey = UTC YYYYMMDD; workflowRevision from $env.N8N_WORKFLOW_REVISION (default 2).
 * - reminderRevisionId = 'rev-' + dayKey + '-' + audience + '-' + workflowRevision.
 * - correlationId is preserved from the upstream envelope (NOT regenerated).
 * - routing === 'FALLBACK' => no sendSyntheticReminder HTTP call; only ack.
 * - reorder-safe: emits items in the upstream stable order.
 */
const upstream = $input.first().json || {};
const items = upstream.items || [];
const dayKey = $now.toUTC().toISO().slice(0, 10).replace(/[-]/g, '');
const workflowRevision = $env.N8N_WORKFLOW_REVISION || '2';
const correlationId = upstream.correlationId;
const organizationId = upstream.organizationId;
const out = [];
for (const it of items) {
  const day = dayKey;
  const aud = it.audience;
  const rev = workflowRevision;
  const idem = 'rem-' + day + '-' + it.nextActionId + '-' + aud + '-r' + rev;
  const ackBase = 'ack-' + day + '-' + it.nextActionId + '-' + aud + '-r' + rev;
  const reminderRevisionId = 'rev-' + day + '-' + aud + '-r' + rev;
  if (it.routing === 'FALLBACK') {
    out.push({
      json: {
        kind: 'fallback',
        logicalId: it.nextActionId + '|' + aud + '|' + day,
        nextActionId: it.nextActionId,
        audience: aud,
        slaBucket: it.slaBucket,
        organizationId: organizationId,
        correlationId: correlationId,
        ackBase: ackBase,
        reminderRevisionId: reminderRevisionId,
        reason: 'no_owner_or_supervisor'
      }
    });
    continue;
  }
  out.push({
    json: {
      kind: 'send',
      logicalId: it.nextActionId + '|' + aud + '|' + day,
      envelope: {
        schemaVersion: '1',
        commandId: ('cmd-' + idem).slice(0, 64),
        commandName: 'sendSyntheticReminder',
        idempotencyKey: idem,
        correlationId: correlationId,
        organizationId: organizationId,
        source: { kind: 'HRP_UI', provider: 'HRP_UI', connectionId: null },
        actor: { kind: 'SERVICE', serviceId: $env.HRP_AUTOMATION_SERVICE_ID },
        automationSource: {
          kind: 'N8N_AUTOMATION',
          workflowId: ($workflow.id),
          workflowRevision: parseInt(workflowRevision, 10),
          n8nExecutionId: ($execution.id),
          workflowLabel: 'sla-reminder-crm'
        },
        operation: {
          op: 'sendSyntheticReminder',
          payload: {
            schemaVersion: '1',
            nextActionId: it.nextActionId,
            audienceKind: aud,
            redactedRecipientId: it.recipientRedacted,
            channel: 'DASHBOARD_ONLY',
            reminderRevisionId: reminderRevisionId
          }
        }
      },
      ackBase: ackBase,
      reminderRevisionId: reminderRevisionId,
      nextActionId: it.nextActionId,
      audience: aud,
      slaBucket: it.slaBucket,
      organizationId: organizationId,
      correlationId: correlationId
    }
  });
}
return out;

/*
 * Ack builder for the SEND branch.
 *  - idempotencyKey = 'ack-' + day + '-' + nextActionId + '-' + audience + '-r' + workflowRevision.
 *  - reminderRevisionId mirrors the send envelope so ack and send can be joined.
 *  - correlationId, organizationId, n8nExecutionId are carried through unchanged.
 *  - notificationOutcome derives from wireStatus (SENT / FAILED / SKIPPED).
 *  - No Date.now() / Math.random(); deterministic ackBase from stable fields only.
 */
const upstream = $input.first().json || {};
const envelope = upstream.envelope;
const wire = upstream.wireStatus;
const outcome = wire === 'APPLIED' ? 'SENT' : (wire === 'SKIPPED' ? 'SKIPPED' : 'FAILED');
return [
  {
    json: {
      source: 'send',
      logicalId: upstream.logicalId,
      correlationId: envelope.correlationId,
      organizationId: envelope.organizationId,
      nextActionId: upstream.nextActionId,
      audience: upstream.audience,
      slaBucket: upstream.slaBucket,
      notificationOutcome: outcome,
      reminderRevisionId: upstream.reminderRevisionId,
      ackBase: upstream.ackBase,
      sendIdempotencyKey: envelope.idempotencyKey,
      sendExecutionId: envelope.automationSource.n8nExecutionId,
      sendCorrelationId: envelope.correlationId
    }
  }
];

/*
 * Ack builder for the FALLBACK branch.
 *  - idempotencyKey = 'ack-skip-' + day + '-' + nextActionId + '-' + audience.
 *  - nextActionId is the logical item id from the upstream list.
 *  - No Date.now() / Math.random().
 *  - notificationOutcome = SKIPPED; channel = DASHBOARD_ONLY; reason preserved.
 */
const fb = $input.first().json || {};
return [
  {
    json: {
      source: 'fallback',
      logicalId: fb.logicalId,
      correlationId: fb.correlationId,
      organizationId: fb.organizationId,
      nextActionId: fb.nextActionId,
      audience: fb.audience,
      slaBucket: fb.slaBucket,
      notificationOutcome: 'SKIPPED',
      reminderRevisionId: fb.reminderRevisionId,
      ackBase: fb.ackBase,
      reason: fb.reason
    }
  }
];

/*
 * Build acknowledgeReminder envelopes. Single point of ack construction.
 * - idempotencyKey = ackBase (carried from upstream; never Date.now() / Math.random()).
 * - correlationId = upstream.correlationId (preserved from the list call).
 * - n8nExecutionId = $execution.id (preserved from workflow host).
 * - Dedupe guard: skip if a logicalId has already been processed in this batch.
 */
const items = $input.all();
const seen = {};
const out = [];
for (const it of items) {
  const j = it.json || {};
  if (!j.ackBase) continue;
  if (seen[j.ackBase]) continue;
  seen[j.ackBase] = true;
  out.push({
    json: {
      envelope: {
        schemaVersion: '1',
        commandId: ('cmd-ack-' + j.ackBase).slice(0, 64),
        commandName: 'acknowledgeReminder',
        idempotencyKey: j.ackBase,
        correlationId: j.correlationId,
        organizationId: j.organizationId,
        source: { kind: 'HRP_UI', provider: 'HRP_UI', connectionId: null },
        actor: { kind: 'SERVICE', serviceId: $env.HRP_AUTOMATION_SERVICE_ID },
        automationSource: {
          kind: 'N8N_AUTOMATION',
          workflowId: ($workflow.id),
          workflowRevision: parseInt($env.N8N_WORKFLOW_REVISION || '2', 10),
          n8nExecutionId: ($execution.id),
          workflowLabel: 'sla-reminder-crm'
        },
        operation: {
          op: 'acknowledgeReminder',
          payload: {
            schemaVersion: '1',
            nextActionId: j.nextActionId,
            notificationOutcome: j.notificationOutcome,
            reminderRevisionId: j.reminderRevisionId,
            channel: 'DASHBOARD_ONLY'
          }
        }
      },
      source: j.source,
      logicalId: j.logicalId
    }
  });
}
return out;
